package com.tripmateai.repository; import com.tripmateai.entity.*; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface FavoriteRepository extends JpaRepository<Favorite,Long> { List<Favorite> findByUser(User user); Optional<Favorite> findByIdAndUser(Long id,User user); boolean existsByUserAndDestination(User user,Destination target); boolean existsByUserAndHotel(User user,Hotel target); boolean existsByUserAndRestaurant(User user,Restaurant target); boolean existsByUserAndAttraction(User user,Attraction target); long countByUserAndDestinationIsNotNull(User user); long countByUserAndHotelIsNotNull(User user); long countByUserAndRestaurantIsNotNull(User user); long countByUserAndAttractionIsNotNull(User user); }
